            c("¿Qué tipo de energía guardan los alimentos y las pilas?", "Energía química", ["Energía solar directa", "Energía eólica", "Energía sonora"], "Al comer o al usar una pila, esa energía se libera.", "🔋"),
            c("¿Cuál de estas es una fuente de energía renovable?", "El sol", ["El petróleo", "El carbón", "El gas natural"], "El sol no se agota en nuestra escala de tiempo.", "☀️"),
            c("¿Por qué el petróleo es una energía no renovable?", "Porque tarda millones de años en formarse", ["Porque es líquido", "Porque es negro", "Porque está en el mar"], "Si lo gastamos, no se recupera pronto."),
            c("¿Qué problema causa quemar carbón, petróleo y gas?", "Contaminan el aire y calientan el planeta", ["Enfrían el planeta", "Limpian el aire", "Hacen crecer los árboles"], "Liberan gases que aumentan el efecto invernadero."),
            c("En un ventilador, la energía eléctrica se transforma principalmente en…", "Energía de movimiento", ["Energía química", "Luz", "Sonido musical"], "El motor hace girar las aspas.", "🌀"),
            c("¿La energía se puede crear de la nada?", "No, se transforma de una forma en otra", ["Sí, con un botón", "Sí, cuando hace calor", "Solo de noche"], "Por ejemplo, la luz del sol se transforma en electricidad."),
            o("Ordena cómo funciona una linterna", ["La pila guarda energía química", "Se transforma en energía eléctrica", "La corriente llega a la bombilla", "La bombilla produce luz y calor"])
